const a={grades:{5:[{id:"G5-REV-01",grade:5,lessonNumber:null,isRevisionModule:!0,title:"REVISION MODULE 1: 5-SINF KIRISH VA TAKRORLASH",topic:"Til va nutq, mustaqil soʻz turkumlari",learningObjective:"Til va nutq, oʻzbek tilining davlat tili maqomi hamda mustaqil soʻz turkumlarini takrorlash.",coreConcept:"Til — kishilar orasidagi aloqa vositasi. Oʻzbek tili — Oʻzbekiston Respublikasining davlat tili (1989-yil).",explanation:"Tilshunoslikning boʻlimlari: fonetika (tovushlar), leksikologiya (soʻz maʼnolari), morfologiya (soʻz shakllari), sintaksis (gap tuzilishi). Mustaqil soʻz turkumlari: ot, sifat, son, olmosh, feʼl.",examples:["kitob (ot)","oq (sifat)","besh (son)","u (olmosh)","yugurmoq (feʼl)"],verificationStatus:"verified",curriculumPosition:1},{id:"G5-L01",grade:5,lessonNumber:1,title:"Oʻzbek alifbosi",topic:"Alifbo va harflar",learningObjective:"Oʻzbek lotin alifbosidagi 29 ta harfni tanib olish, alifbo tartibida yozish va harflarni toʻgʻri yozish.",prerequisites:"Harf va tovush farqi haqida tushuncha.",coreConcept:"Oʻzbek alifbosi lotin yozuviga asoslangan boʻlib, 29 ta harfdan iborat. Har bir harf bir yoki bir necha tovushni ifodalaydi.",explanation:"Oʻzbek tilida 29 ta harf mavjud. Harflar alifbo tartibida joylashgan. Baʼzi harflar (oʻ, gʻ, sh, ch, ng) oʻzbek tiliga xos boʻlib, boshqa tillarda uchramaydi.",examples:["A — olma, ona","B — bola, kitob","Oʻ — oʻrik, koʻk","Gʻ — gʻoz, bogʻ","Sh — shahar, ish","Ch — choy, oycha","Ng — tong, rang"],commonMistakes:["Oʻ harfini O dan farqlamaslik — ot (hayvon) va oʻt (oʻsimlik) maʼnosi farq qiladi.","Gʻ harfini G bilan adashtirish — gul va gʻul (tovush) farqi.","Sh va Ch harflarini alohida talaffuz qilish — sh bir tovush, sh+h emas."],guidedPractice:["Oʻqituvchi rahbarligida alifbo tartibida harflarni takrorlash.","Berilgan soʻzlardagi harflarni nomlab koʻrsatish."],independentPractice:["Alifbo tartibida 10 ta harf yozing.","Ismingizdagi harflarni alifbo tartibida yozing.","Quyidagi soʻzlarni alifbo tartibida joylashtiring: olma, kitob, daftar, qalam, ruchka"],answersExplanations:["1. Talaba ixtiyoriga qoldiriladi.","2. Masalan: Ali → A, i, l","3. daftar, kitob, olma, qalam, ruchka"],lessonRecap:"Oʻzbek alifbosi 29 ta harfdan iborat. Harflarni toʻgʻri yozish va talaffuz qilish — savodli yozishning asosidir.",verificationStatus:"verified",curriculumPosition:2},{id:"G5-L02",grade:5,lessonNumber:2,title:"E va Oʻ unlilari imlosi",topic:"Unlilar imlosi",learningObjective:"E va Oʻ unlilarini soʻzlarda toʻgʻri yozish.",prerequisites:"Unli tovushlar (Dars 1), talaffuz va imlo farqi.",coreConcept:"Ayrim soʻzlarda e tovushi i kabi, oʻ tovushi u kabi yoki o kabi talaffuz qilinsa ham, asl shakli boʻyicha yoziladi.",explanation:"E harfi yoziladi: kema, kelmoq, elak, meva, sekin. Oʻ harfi yoziladi: oʻrik, koʻk, soʻz, yoʻl, boʻgʻin.",rules:["E harfi soʻz boshida, oʻrtasida va oxirida kelishi mumkin.","Oʻ harfi faqat soʻz boshida yoki oʻrtasida keladi.","Baʼzi soʻzlarda e va oʻ ni almashtirib boʻlmaydi — maʼno oʻzgaradi."],examples:["Kema (kima emas)","Kelmoq (kilmoq emas)","Oʻrik (urik yoki orik emas)","Soʻz (suz yoki soz emas)","Yoʻl (yul yoki yol emas)"],commonMistakes:["kima → kema","kilmoq → kelmoq","urik → oʻrik","suz → soʻz","yol → yoʻl"],guidedPractice:["kima → kema","urik → oʻrik","kilmoq → kelmoq","soz → soʻz"],independentPractice:["10 ta soʻz yozing, ularda e va oʻ harflarini toʻgʻri qoʻllang.","Berilgan soʻzlarni koʻchiring: kema, oʻrik, meva, soʻz, yoʻl, elak, boʻgʻin, kelmoq, koʻk, sekin"],answersExplanations:["Kema, oʻrik, meva, soʻz, yoʻl, elak, boʻgʻin, kelmoq, koʻk, sekin"],lessonRecap:"E va Oʻ harflari talaffuzda boshqa tovushlarga yaqin boʻlsa ham, asl shakli boʻyicha yoziladi.",verificationStatus:"verified",curriculumPosition:3},{id:"G5-L03",grade:5,lessonNumber:3,title:"Yonma-yon kelgan unlilar imlosi",topic:"Unlilar imlosi",learningObjective:"Yonma-yon kelgan unlilarni toʻgʻri yozish.",prerequisites:"Unli tovushlar, alifbo.",coreConcept:"Yonma-yon kelgan unlilar — bir soʻz ichida ikkita unli tovushning ketma-ket kelishi. Bunday soʻzlar asosan boshqa tillardan oʻzlashgan.",explanation:"Oʻzbek tilida unlilar odatda yonma-yon kelmaydi. Ammo oʻzlashma soʻzlarda ikkita unli yonma-yon kelishi mumkin: taom, maosh, faol, maʼno, biolog, pioner.",rules:["a+o: taom, maosh, faol","a+u: maʼno, daʼvo, maʼlum","i+o: biolog, pioner, diod","o+a: koala, poema","u+a: duala, buat"],examples:["taom","maosh","faol","maʼno","biolog","pioner"],commonMistakes:["Yonma-yon unlilarni alohida boʻgʻin deb hisoblash — ta-om emas, taom","Tutuq belgisini qoʻymaslik — mano emas, maʼno","Qoʻshimchada unlilarni notoʻgʻri yozish — taomga"],guidedPractice:["taom","maosh","faol","biolog","pioner","maʼno"],independentPractice:["5 ta yonma-yon unli ishtirok etgan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["taom, maosh, faol, biolog, pioner, maʼno"],lessonRecap:"Yonma-yon kelgan unlilar — bir soʻz ichida ikkita unlining ketma-ket kelishi.",verificationStatus:"verified",curriculumPosition:4},{id:"G5-L04",grade:5,lessonNumber:4,title:"Q va Gʻ undoshlari imlosi",topic:"Undoshlar imlosi",learningObjective:"Q va Gʻ undoshlarini soʻzlarda toʻgʻri yozish.",prerequisites:"Undosh tovushlar (Dars 2).",coreConcept:"Q va Gʻ — oʻzbek tiliga xos tovushlar. Ular til orqa qismi yordamida hosil qilinadi.",explanation:"Q — jarangsiz, til orqa undoshi: qoʻl, qogʻoz, oq, toq. Gʻ — jarangli, chuqur til orqa undoshi: gʻoz, bogʻ, gʻalla, togʻ.",rules:["Q va Gʻ harflari soʻz boshida, oʻrtasida va oxirida kelishi mumkin.","Qoʻshimcha qoʻshilganda Q va Gʻ imlosi oʻzgarmaydi.","Q va Gʻ ni adashtirish maʼno oʻzgarishiga olib keladi."],examples:["qoʻl (gʻoʻl emas)","oq (ogʻ emas)","gʻoz (qoz emas)","bogʻ (boq emas)","gʻalla (qalla emas)"],commonMistakes:["gʻoʻl → qoʻl","ogʻ → oq","qoz → gʻoz","boq → bogʻ","qalla → gʻalla"],guidedPractice:["Q: qoʻl, qogʻoz, oq, toq","Gʻ: gʻoz, bogʻ, gʻalla, togʻ"],independentPractice:["Q va Gʻ ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["Q: qoʻl, qogʻoz, oq, toq, qalam; Gʻ: gʻoz, bogʻ, gʻalla, togʻ, gʻam","qoʻl, oq, gʻoz, bogʻ, gʻalla"],lessonRecap:"Q — jarangsiz, Gʻ — jarangli undoshlar. Q va Gʻ ni adashtirish soʻz maʼnosini oʻzgartiradi.",verificationStatus:"verified",curriculumPosition:5},{id:"G5-L05",grade:5,lessonNumber:5,title:"D va T undoshlari imlosi",topic:"Undoshlar imlosi",learningObjective:"D va T undoshlarini soʻzlarda toʻgʻri yozish.",prerequisites:"Undosh tovushlar, jarangli va jarangsiz undoshlar.",coreConcept:"D — jarangli, T — jarangsiz undosh. Ayrim soʻzlarda D tovushi T kabi talaffuz qilinsa ham, asl shakli boʻyicha D yoziladi.",explanation:"Soʻz oxirida D va T tovushlari orasidagi farq yoʻqoladi (D ham, T ham T kabi talaffuz qilinadi). Lekin yozuvda D saqlanadi: bogʻd, ot, daftar, xat.",rules:["Soʻz oxirida D yoziladi, lekin T kabi talaffuz qilinadi.","Qoʻshimcha qoʻshilganda D ovozi eshitiladi: bogʻda, sovda, kitobda.","T harfi soʻz boshida va oʻrtasida kelishi mumkin.","D va T ni adashtirish maʼno oʻzgarishiga olib keladi: odim (qadam) — otim (mening otim)."],examples:["bogʻd (bogʻt deb talaffuz qilinadi)","sovd","kitobd","tosh","ot"],commonMistakes:["Soʻz oxirida D ni T deb yozish: bogʻt → bogʻd","D va T ni soʻz boshida adashtirish: dos → tos (tosh)"],guidedPractice:["bogʻd, sovd, kitobd, daftar","tosh, ot, xat, taroq","bogʻda, sovda, kitobda"],independentPractice:["D va T ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating: bogʻt, sovt, kitobt, dos, xad"],answersExplanations:["D: bogʻd, sovd, kitobd, daftar, odim; T: tosh, ot, xat, taroq, tish","bogʻd, sovd, kitobd, tosh, xat"],lessonRecap:"D — jarangli, T — jarangsiz. Soʻz oxirida D yoziladi, lekin T kabi talaffuz qilinadi.",verificationStatus:"verified",curriculumPosition:6},{id:"G5-L06",grade:5,lessonNumber:6,title:"J va DJ undoshlari imlosi",topic:"Undoshlar imlosi",learningObjective:"J va DJ undoshlarini soʻzlarda toʻgʻri yozish.",prerequisites:"Undosh tovushlar, jarangli undoshlar.",coreConcept:"J va DJ — ikkalasi ham jarangli undoshlar. J bitta harf, DJ ikkita harf birikmasi.",explanation:"J — bitta tovush, bitta harf: joʻja, jahon, jilva, ojoq. DJ — bitta tovush, lekin ikkita harf: djoʻgari, tajdid.",rules:["J — asosan oʻzbekcha va forscha soʻzlarda: jongʻor, jahon, jilva.","DJ — asosan arabcha soʻzlarda va baʼzi nomlarda: djoʻgari, tajdid.","DJ ni alohida D+J deb talaffuz qilish notoʻgʻri — bitta tovush."],examples:["joʻja","jahon","jilva","djoʻgari","tajdid"],commonMistakes:["J ni DJ deb yozish: djahon → jahon","DJ ni J deb yozish: jogari → djoʻgari"],guidedPractice:["joʻja, jahon, jilva, ojoq","djoʻgari, tajdid"],independentPractice:["J va DJ ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["J: joʻja, jahon, jilva, ojoq, jon; DJ: djoʻgari, tajdid, hojat","jahon, djoʻgari, joʻja"],lessonRecap:"J bitta harf, DJ ikkita harf birikmasi.",verificationStatus:"verified",curriculumPosition:7},{id:"G5-L07",grade:5,lessonNumber:7,title:"F va V undoshlari imlosi",topic:"Undoshlar imlosi",learningObjective:"F va V undoshlarini soʻzlarda toʻgʻri yozish.",prerequisites:"Undosh tovushlar, lab undoshlari.",coreConcept:"F — jarangsiz, V — jarangli lab undoshlari. F asosan oʻzlashma soʻzlarda, V esa oʻzbekcha va oʻzlashma soʻzlarda qoʻllanadi.",explanation:"F — jarangsiz lab undoshi: fam, sifat, kilof, fon, farq. V — jarangli lab undoshi: vatan, vasl, vosit, vino, televizor.",rules:["F asosan arab, fors, rus tillaridan oʻzlashgan soʻzlarda: fam, farq, fon, sifat.","V oʻzbekcha va boshqa tillardan oʻzlashgan soʻzlarda: vatan, vasl, vosit.","F va V ni adashtirish maʼno oʻzgarishiga olib keladi."],examples:["farq (varq emas)","fon (von emas)","vatan (fatan emas)","vosit (fosit emas)","televizor (telefizor emas)"],commonMistakes:["varq → farq","von → fon","fatan → vatan","fosit → vosit","telefizor → televizor"],guidedPractice:["farq, fon, fam, sifat","vatan, vasl, vosit, televizor"],independentPractice:["F va V ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["F: farq, fon, fam, sifat, foyda; V: vatan, vasl, vosit, televizor, vino","farq, fon, vatan, vosit, televizor"],lessonRecap:"F — jarangsiz, V — jarangli lab undoshlari.",verificationStatus:"verified",curriculumPosition:8},{id:"G5-L08",grade:5,lessonNumber:8,title:"X va H undoshlari imlosi",topic:"Undoshlar imlosi",learningObjective:"X va H undoshlarini soʻzlarda toʻgʻri yozish.",prerequisites:"Undosh tovushlar.",coreConcept:"X — til orqa, H — boʻgʻiz undoshlari. Ikkalasi ham jarangsiz.",explanation:"X — til orqa, jarangsiz: xat, xalq, xona, oxir, toʻxta. H — boʻgʻiz, jarangsiz: havo, hikmat, hamma, oh, mahall.",rules:["H — oʻzbekcha va arabcha soʻzlarda: havo, hikmat, hamma, mahall.","X — fors-tojik va rus tillaridan oʻzlashgan soʻzlarda: xat, xalq, xona, oxir.","X va H ni adashtirish maʼno oʻzgarishiga olib keladi."],examples:["xat (hat emas)","xalq (halq emas)","havo (xavo emas)","hikmat (xikmat emas)","oh (ox emas)"],commonMistakes:["hat → xat","halq → xalq","xavo → havo","xikmat → hikmat","ox → oh"],guidedPractice:["xat, xalq, xona, oxir, toʻxta","havo, hikmat, hamma, oh, mahall"],independentPractice:["X va H ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["X: xat, xalq, xona, oxir, toʻxta; H: havo, hikmat, hamma, oh, mahall","xat, xalq, havo, hikmat, oh"],lessonRecap:"X — til orqa, H — boʻgʻiz undoshlari.",verificationStatus:"verified",curriculumPosition:9},{id:"G5-L09",grade:5,lessonNumber:9,title:"Z va S undoshlari imlosi",topic:"Undoshlar imlosi",learningObjective:"Z va S undoshlarini soʻzlarda toʻgʻri yozish.",prerequisites:"Undosh tovushlar, jarangli va jarangsiz undoshlar.",coreConcept:"Z — jarangli, S — jarangsiz. Z tovushi baʼzan S kabi talaffuz qilinsa ham, asl shakli boʻyicha Z yoziladi.",explanation:"Z — jarangli: zamin, zor, oz, boz, koʻz. S — jarangsiz: suv, som, osmon, tos, bos.",rules:["Soʻz oxirida Z yoziladi, lekin S kabi talaffuz qilinishi mumkin.","Qoʻshimcha qoʻshilganda Z ovozi eshitiladi: ozda, bozda, koʻzda.","S harfi soʻz boshida, oʻrtasida va oxirida kelishi mumkin.","Z va S ni adashtirish maʼno oʻzgarishiga olib keladi."],examples:["oz","boz","koʻz","suv","osmon"],commonMistakes:["Soʻz oxirida Z ni S deb yozish: os → oz","zuv → suv","ozmon → osmon"],guidedPractice:["oz, boz, koʻz, zamin, zor","suv, som, osmon, tos, bos"],independentPractice:["Z va S ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["Z: oz, boz, koʻz, zamin, zor; S: suv, som, osmon, tos, bos","oz, boz, koʻz, suv, osmon"],lessonRecap:"Z — jarangli, S — jarangsiz. Soʻz oxirida Z yoziladi.",verificationStatus:"verified",curriculumPosition:10},{id:"G5-L10",grade:5,lessonNumber:10,title:"Sh, Ch harflar birikmasi",topic:"Harf birikmalari",learningObjective:"Sh va Ch harflar birikmasini toʻgʻri yozish va talaffuz qilish.",prerequisites:"Undosh tovushlar, harf birikmalari.",coreConcept:"Sh va Ch — ikkitadan harf birikmasi boʻlib, bitta tovushni ifodalaydi. Sh — jarangsiz, Ch — jarangli undosh.",explanation:"Sh — jarangsiz, bitta tovush: shahar, ish, shosh, shol. Ch — jarangli, bitta tovush: choy, ich, choch, chal.",rules:["Sh va Ch harflar birikmasi bitta tovushni ifodalaydi.","Tutuq belgisi bilan farqlanadi: shoir (sho-ir) va shoʻr.","Sh va Ch ni alohida talaffuz qilish notoʻgʻri."],examples:["shahar","ish","choy","ich","shol"],commonMistakes:["Sh ni S+H deb talaffuz qilish","Ch ni CH+H deb talaffuz qilish","shor → shoʻr"],guidedPractice:["shahar, ish, shosh, shol","choy, ich, choch, chal"],independentPractice:["Sh va Ch ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["Sh: shahar, ish, shosh, shol, shirin; Ch: choy, ich, choch, chal, chiroq","shahar, ish, choy, ich, shoʻr"],lessonRecap:"Sh va Ch — ikkitadan harf birikmasi boʻlib, bitta tovushni ifodalaydi.",verificationStatus:"verified",curriculumPosition:11},{id:"G5-L11",grade:5,lessonNumber:11,title:"Ng harflar birikmasi",topic:"Harf birikmalari",learningObjective:"Ng harflar birikmasini toʻgʻri yozish va uni n+g dan farqlash.",prerequisites:"Undosh tovushlar, harf birikmalari.",coreConcept:"Ng — ikkita harf birikmasi boʻlib, bitta tovushni ifodalaydi. Bu tovush til orqa, jarangli undoshdir.",explanation:"Ng — bitta tovush: tong, rang, song, qoʻngʻiroq. n+g — ikkita tovush: yangil.",rules:["Ng bitta tovush — tong (to-ng)","Soʻz oxirida ng kelganda, g tovushi eshitilmaydi.","Qoʻshimcha qoʻshilganda ng saqlanadi: tongda, rangda.","Ng ni n+g dan farqlash: tong (bitta) vs yangil (n+g — ikkita)."],examples:["tong","rang","song","qoʻngʻiroq","yangil (n+g)"],commonMistakes:["Ng ni n+g deb yozish: togʻ (tong maʼnosida)","Ng ni n+g deb talaffuz qilish"],guidedPractice:["tong, rang, song, qoʻngʻiroq","yangil, yon-gʻir, un-gʻur, qan-ga"],independentPractice:["Ng va n+g ishtirok etgan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["Ng: tong, rang, song, qoʻngʻiroq, bong; n+g: yangil, yon-gʻir, un-gʻur, qan-ga, yengil","tong, rang, song"],lessonRecap:"Ng — ikkita harf birikmasi boʻlib, bitta tovushni ifodalaydi. Uni n+g dan farqlash muhim.",verificationStatus:"verified",curriculumPosition:12},{id:"G5-L12",grade:5,lessonNumber:12,title:"Qoʻsh undoshlar imlosi",topic:"Undoshlar imlosi",learningObjective:"Qoʻsh undoshlarni toʻgʻri yozish.",prerequisites:"Undosh tovushlar.",coreConcept:"Qoʻsh undoshlar — bir xil ikkita undoshning yonma-yon kelishi. Asosan oʻzlashma soʻzlarda uchraydi.",explanation:"Oʻzbek tilida qoʻsh undoshlar (ikki bir xil undosh) asosan boshqa tillardan kirgan soʻzlarda qoʻllanadi: mass, klass, apparat, programma.",rules:["Qoʻsh undoshlar asosan oʻzlashma soʻzlarda.","Qoʻsh undoshlar qoʻshimcha qoʻshilganda ham saqlanadi.","Qoʻsh undoshlarni alohida talaffuz qilish kerak.","Qoʻsh undoshlarni bitta undosh deb yozish notoʻgʻri."],examples:["mass","klass","apparat","programma","jamoatchilik"],commonMistakes:["mas → mass","klas → klass","aparat → apparat","programa → programma"],guidedPractice:["mass, klass, apparat, programma","jamoatchilik, qoʻshimcha"],independentPractice:["Qoʻsh undoshlar ishtirok etgan 5 ta soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["mass, klass, apparat, programma, jamoatchilik","mass, klass, apparat, programma"],lessonRecap:"Qoʻsh undoshlar — bir xil ikkita undoshning yonma-yon kelishi.",verificationStatus:"verified",curriculumPosition:13},{id:"G5-L13",grade:5,lessonNumber:13,title:"Qator undoshlar imlosi",topic:"Undoshlar imlosi",learningObjective:"Qator undoshlarni toʻgʻri yozish.",prerequisites:"Undosh tovushlar.",coreConcept:"Qator undoshlar — turli xil undoshlarning yonma-yon kelishi. Oʻzbek tilida qator undoshlar asosan oʻzlashma soʻzlarda uchraydi.",explanation:"Qator undoshlar — ikki yoki undan ortiq turli undoshlarning ketma-ket kelishi: akst, sent, bank, fakt, shkaf.",rules:["Qator undoshlar asosan oʻzlashma soʻzlarda: akst, sent, bank, fakt, shkaf.","Qoʻshimcha qoʻshilganda qator undoshlar saqlanadi: akst+ga → akstga.","Qator undoshlarni toʻgʻri talaffuz qilish kerak.","Qator undoshlarni alohida yoki orttirib yozmaslik."],examples:["akst","sent","bank","fakt","shkaf"],commonMistakes:["akstt → akst","akt → akst","sentt → sent"],guidedPractice:["akst, sent, bank, fakt, shkaf"],independentPractice:["Qator undoshlar ishtirok etgan 5 ta soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["akst, sent, bank, fakt, shkaf, sport","akst, sent"],lessonRecap:"Qator undoshlar — turli xil undoshlarning yonma-yon kelishi.",verificationStatus:"verified",curriculumPosition:14},{id:"G5-L14",grade:5,lessonNumber:14,title:"Tovush ortishi",topic:"Fonetik hodisalar",learningObjective:"Tovush ortishi hodisasini tushunish va toʻgʻri yozish.",prerequisites:"Tovush oʻzgarishlari, qoʻshimchalar.",coreConcept:"Tovush ortishi — soʻzga qoʻshimcha qoʻshilganda yangi tovushning paydo boʻlishi.",explanation:"Ayrim soʻzlarga qoʻshimcha qoʻshilganda ular orasida yangi tovush paydo boʻladi.",rules:["Unli bilan tugagan soʻzga unli bilan boshlangan qoʻshimcha qoʻshilganda y tovushi ortadi: bola+ing → bolaying.","Tovush ortishi asosan soʻzlashuv nutqida koʻp uchraydi.","Yozuvda tovush ortishi aks etmaydi — asl shakli saqlanadi."],examples:["bola+ing → bolaying (soʻzlashuvda)","ota+ing → otayng (soʻzlashuvda)"],commonMistakes:["Tovush ortishini yozuvda aks ettirish [VERIFY] — Aslida bu soʻzlashuv hodisasi, yozuvda aks etmaydi."],guidedPractice:["bola + ing → bolayng","ota + im → otaym","kema + da → kemada"],independentPractice:["Tovush ortishi ishtirok etgan 5 ta misol yozing."],answersExplanations:["bolayng (soʻzlashuvda), otaym (soʻzlashuvda), kemada (ortmaydi)","[VERIFY] — Bu asosan soʻzlashuv nutqiga oid, yozuvda aks etmaydi."],lessonRecap:"Tovush ortishi — soʻzga qoʻshimcha qoʻshilganda yangi tovushning paydo boʻlishi.",verificationStatus:"needs_verification",verificationNotes:["Common mistakes and spelling rule details contain [VERIFY] marker regarding spoken vs written representation."],curriculumPosition:15},{id:"G5-L15",grade:5,lessonNumber:15,title:"Tovush tushishi",topic:"Fonetik hodisalar",learningObjective:"Tovush tushishi hodisasini tushunish va toʻgʻri yozish.",prerequisites:"Tovush oʻzgarishlari, qoʻshimchalar.",coreConcept:"Tovush tushishi — soʻzga qoʻshimcha qoʻshilganda soʻz tarkibidagi baʼzi tovushlarning tushib qolishi.",explanation:"Ayrim soʻzlarga qoʻshimcha qoʻshilganda soʻzdagi bir tovush tushib qoladi: katta+roq → kattaroq.",rules:["katta+roq → kattaroq (t tushadi)","katta+gina → kattagina (t tushadi)","kichik+roq → kichikroq (tushmaydi)","Tovush tushishi yozuvda aks etadi — asl shakli oʻzgaradi."],examples:["kattaroq","kattagina","kichikroq","yangiroq"],commonMistakes:["Tovush tushishini yozuvda aks ettirmaslik [VERIFY] — Tushgan tovushni yozmaslik kerak."],guidedPractice:["katta + roq → kattaroq","katta + gina → kattagina","kichik + roq → kichikroq"],independentPractice:["Tovush tushishi ishtirok etgan 5 ta misol yozing."],answersExplanations:["kattaroq, kattagina, kichikroq","kattaroq, kattagina (t tushadi), kichikroq (tushmaydi)"],lessonRecap:"Tovush tushishi — soʻzga qoʻshimcha qoʻshilganda soʻzdagi baʼzi tovushlarning tushib qolishi.",verificationStatus:"needs_verification",verificationNotes:["Contains [VERIFY] flag on whether fallen sound should be omitted in spelling."],curriculumPosition:16},{id:"G5-L16",grade:5,lessonNumber:16,title:"Tovush almashishi",topic:"Fonetik hodisalar",learningObjective:"Tovush almashishi hodisasini tushunish va toʻgʻri yozish.",prerequisites:"Tovush oʻzgarishlari, qoʻshimchalar.",coreConcept:"Tovush almashishi — soʻzga qoʻshimcha qoʻshilganda bir tovushning boshqa tovushga almashishi.",explanation:"Ayrim soʻzlarga qoʻshimcha qoʻshilganda soʻzdagi bir tovush boshqa tovushga almashadi.",rules:["yuz+ga → yuzga","gul+ga → gulga","kitob+da → kitobda","[VERIFY] — Oʻzbek tilida tovush almashishi kam uchraydi."],examples:["qoʻl+da → qoʻlda","suz+da → suzda","koʻz+da → koʻzda"],commonMistakes:["[VERIFY] — Oʻzbek tilida tovush almashishi haqida koʻproq maʼlumot kerak."],guidedPractice:["qoʻl + da → qoʻlda","suz + da → suzda","koʻz + da → koʻzda"],independentPractice:["Tovush almashishi ishtirok etgan 5 ta misol yozing.","[VERIFY] — Oʻzbek tilida tovush almashishi misollari kam."],answersExplanations:["qoʻlda, suzda, koʻzda (hech birida almashish yoʻq)","[VERIFY] — Oʻzbek tilida tovush almashishi misollari kam."],lessonRecap:"Tovush almashishi — soʻzga qoʻshimcha qoʻshilganda bir tovushning boshqa tovushga almashishi. [VERIFY] — Koʻproq misol kerak.",verificationStatus:"needs_verification",verificationNotes:["Multiple [VERIFY] tags detected regarding applicability and examples of sound substitution in Uzbek."],curriculumPosition:17},{id:"G5-L17",grade:5,lessonNumber:17,title:"Urgʻu",topic:"Fonetika va talaffuz",learningObjective:"Soʻz va gap urgʻusini tushunish va toʻgʻri qoʻllash.",prerequisites:"Boʻgʻin (Dars 3).",coreConcept:"Urgʻu — soʻz yoki gapning bir boʻgʻinining boshqalariga nisbatan kuchliroq talaffuz qilinishi.",explanation:"Soʻz urgʻusi — soʻz ichidagi bir boʻgʻinning kuchliroq talaffuz qilinishi: kalta, keladik, daftar. Gap urgʻusi — gapdagi bir soʻzning kuchliroq talaffuz qilinishi: Bugun havo issiq.",rules:["Oʻzbek tilida urgʻu odatda soʻzning oxirgi boʻgʻiniga tushadi: olti, kitob, daftar.","Baʼzi soʻzlarda urgʻu oldingi boʻgʻinlarga tushishi mumkin: katta, appa, panjara.","Urgʻu soʻz maʼnosini farqlashi mumkin.","Gap urgʻusi maʼno va emotsiyani ifodalaydi."],examples:["kitób","daftár","kátta","áppa"],commonMistakes:["Urgʻuni notoʻgʻri qoʻyish","Urgʻuni hisobga olmaslik"],guidedPractice:["kitob, daftar, olma","katta, appa, panjara"],independentPractice:["Urgʻu qoʻyib 5 ta soʻz yozing.","Urgʻu maʼno farqlaydigan 5 ta juft soʻz yozing."],answersExplanations:["kitób, daftár, olmá, kátta, áppa","ót (oʻt) — ot (hayvon), áqil (aql) — aqíl (harakat)"],lessonRecap:"Urgʻu — soʻz yoki gapning bir boʻgʻinining kuchliroq talaffuz qilinishi. Oʻzbek tilida urgʻu odatda oxirgi boʻgʻinga tushadi.",verificationStatus:"verified",curriculumPosition:18},{id:"G5-L18",grade:5,lessonNumber:18,title:"Qoʻshib va ajratib yozish",topic:"Orfografiya",learningObjective:"Qoʻshib va ajratib yoziladigan soʻzlarni toʻgʻri yozish.",prerequisites:"Soʻz tuzilishi.",coreConcept:"Baʼzi soʻzlar qoʻshib, baʼzi soʻzlar ajratib yoziladi. Qoʻshib yozish asosan qoʻshma soʻzlar, ajratib yozish esa ayrim yordamchi soʻzlar va olmoshlar uchun xos.",explanation:"Qoʻshib yoziladi: qoʻziqorin, belkurak, oqqush, kungaboqar. Ajratib yoziladi: har bir, hech kim, hech narsa, shu bilan, oʻsha vaqt.",rules:["Qoʻshma soʻzlar qoʻshib yoziladi: qoʻziqorin, belkurak, oqqush.","Har, hech, bir, shu, oʻsha, hamma soʻzlari bilan kelgan birikmalar ajratib yoziladi: har bir, hech kim, shu bilan, oʻsha payt.","Yordamchi soʻzlar ajratib yoziladi: bilan, uchun, kabi, ham, faqat.","Juft va takroriy soʻzlar chiziqcha bilan yoziladi: ota-ona, choy-poy."],examples:["qoʻziqorin","belkurak","har bir","hech kim","shu bilan"],commonMistakes:["harbir → har bir","hechkim → hech kim","shubilan → shu bilan","qoʻzi qorin → qoʻziqorin","bel kurak → belkurak"],guidedPractice:["qoʻziqorin","belkurak","har bir","hech kim"],independentPractice:["Qoʻshib va ajratib yoziladigan 5 tadan soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["Qoʻshib: qoʻziqorin, belkurak, oqqush, kungaboqar, qizilishton; Ajratib: har bir, hech kim, shu bilan, oʻsha vaqt, ham","har bir, hech kim, shu bilan, qoʻziqorin, belkurak"],lessonRecap:"Qoʻshma soʻzlar qoʻshib, har/hech/bir/shu/oʻsha bilan kelgan birikmalar ajratib yoziladi.",verificationStatus:"verified",curriculumPosition:19},{id:"G5-L19",grade:5,lessonNumber:19,title:"Chiziqcha bilan yozish",topic:"Orfografiya",learningObjective:"Chiziqcha qoʻllash qoidalarini bilish va toʻgʻri qoʻllash.",prerequisites:"Qoʻshib va ajratib yozish.",coreConcept:"Chiziqcha (-) — soʻzlar orasiga yoki qoʻshimchalardan oldin qoʻyiladigan belgi. Juft va takroriy soʻzlar, baʼzi qoʻshimchalar chiziqcha bilan yoziladi.",explanation:"Juft soʻzlar: ota-ona, qarindosh-urugʻ, qizil-gul. Takroriy soʻzlar: choy-poy, uy-puy, tuz-puz. Baʼzi qoʻshimchalar: -u(-yu), -chi, -ku, -da.",rules:["Juft soʻzlar chiziqcha bilan yoziladi: ota-ona, qarindosh-urugʻ.","Takroriy soʻzlar chiziqcha bilan yoziladi: choy-poy, uy-puy.","-u(-yu), -chi, -ku, -da qoʻshimchalari chiziqcha bilan yoziladi: bora-bora, kelin-ku, bola-chi.","Chiziqcha soʻzlarni bir-biriga bogʻlaydi yoki ularni ajratadi."],examples:["ota-ona","qarindosh-urugʻ","choy-poy","bora-bora","kelin-ku"],commonMistakes:["otaona → ota-ona","qarindoshurugʻ → qarindosh-urugʻ","choypoy → choy-poy","borabora → bora-bora"],guidedPractice:["ota-ona","qarindosh-urugʻ","choy-poy","bora-bora"],independentPractice:["Chiziqcha bilan yoziladigan 5 ta soʻz yozing.","Xato yozilgan soʻzlarni tuzating."],answersExplanations:["ota-ona, qarindosh-urugʻ, choy-poy, bora-bora, uy-puy","ota-ona, qarindosh-urugʻ, choy-poy, bora-bora"],lessonRecap:"Juft va takroriy soʻzlar, -u(-yu), -chi, -ku, -da qoʻshimchalari chiziqcha bilan yoziladi.",verificationStatus:"verified",curriculumPosition:20},{id:"G5-L20",grade:5,lessonNumber:20,title:"Omonim va paronim soʻzlar",topic:"Leksikologiya",learningObjective:"Omonim va paronim soʻzlarni taniy olish va farqlash.",prerequisites:"Soʻz maʼnosi tushunchasi.",coreConcept:"Omonimlar — aytilishi va yozilishi bir xil, maʼnosi har xil soʻzlar. Paronimlar — aytilishi va yozilishi yaqin, maʼnosi farq qiladigan soʻzlar.",explanation:"Omonimlar: burun (yuz qismi) va burun (avval); un (tovush) va un (mahsulot). Paronimlar: maʼnaviy (ruhiy) va moddiy (jismoniy).",rules:["Omonimlar bir xil yoziladi va aytiladi, lekin maʼnosi farq qiladi.","Paronimlar yaqin yoziladi va aytiladi, lekin maʼnosi farq qiladi.","Omonim va paronimlarni kontekst orqali farqlash mumkin.","Omonim va koʻp maʼnoli soʻzlarni farqlash: koʻp maʼnoli soʻz — bitta soʻz, turli maʼnolar; omonim — turli soʻzlar."],examples:["burun (yuz) vs burun (avval)","un (tovush) vs un (mahsulot)","dam (nafas) vs dam (payt)","maʼnaviy vs moddiy"],commonMistakes:["Omonimni koʻp maʼnoli soʻz bilan adashtirish.","Paronimlarning maʼnosini bilmaslik."],guidedPractice:["burun (yuz) — burun (avval) → omonim","un (tovush) — un (mahsulot) → omonim","maʼnaviy — moddiy → paronim"],independentPractice:["Omonim soʻzlarga 5 ta misol yozing.","Paronim soʻzlarga 3 ta misol yozing."],answersExplanations:["omonim, omonim, paronim"],lessonRecap:"Omonimlar — yozilishi va aytilishi bir xil, maʼnosi har xil. Paronimlar — yozilishi va aytilishi yaqin, maʼnosi har xil soʻzlar.",verificationStatus:"verified",curriculumPosition:21},{id:"G5-L21",grade:5,lessonNumber:21,title:"Oʻz va oʻzlashgan soʻzlar",topic:"Leksikologiya",learningObjective:"Oʻzbekcha va oʻzlashgan soʻzlarni ajrata olish.",prerequisites:"Soʻz maʼnosi tushunchasi.",coreConcept:"Oʻzbek tili lugʻati oʻzbekcha soʻzlar va boshqa tillardan kirgan oʻzlashgan soʻzlardan iborat.",explanation:"Oʻzbekcha soʻzlar: ota, ona, bola, suv, yer, osmon. Oʻzlashgan soʻzlar: kitob (arab), daftar (arab), maktab (arab), bogʻ (fors), stol (rus), kompyuter (ingliz).",rules:["Oʻzbekcha soʻzlar asli oʻzbek tiliga tegishli.","Oʻzlashgan soʻzlar boshqa tillardan kirgan.","Oʻzlashgan soʻzlar oʻzbek tilining imlo qoidalariga moslashgan.","Oʻzlashgan soʻzlar koʻpincha oʻziga xos imloga ega."],examples:["ota, ona, bola, suv, yer","kitob (arab), maktab (arab), bogʻ (fors), stol (rus), kompyuter (ingliz)"],commonMistakes:["Oʻzlashgan soʻzlarni notoʻgʻri talaffuz qilish: kampyuter → kompyuter","Oʻzlashgan soʻzlarni oʻzbekcha deb hisoblash."],guidedPractice:["Oʻzbekcha: ota, ona, bola","Oʻzlashgan: kitob, daftar, maktab"],independentPractice:["Oʻzbekcha va oʻzlashgan soʻzlarga 5 tadan misol yozing."],answersExplanations:["Oʻzbekcha: ota, ona, bola, suv, yer; Oʻzlashgan: kitob, daftar, maktab, bogʻ, stol","kitob (arab), maktab (arab), bogʻ (fors), stol (rus), kompyuter (ingliz)"],lessonRecap:"Oʻzbek tili lugʻati oʻzbekcha va oʻzlashgan soʻzlardan iborat.",verificationStatus:"verified",curriculumPosition:22}],6:[{id:"G6-REV-02",grade:6,lessonNumber:null,isRevisionModule:!0,title:"REVISION MODULE 2: 6-SINF TAKRORLASH",topic:"Fonetika, imlo, leksikologiya, lugʻatshunoslik",learningObjective:"5-sinfda oʻtilgan fonetika, imlo va leksikologiya boʻlimlarini takrorlash va mustahkamlash.",coreConcept:"Fonetika, imlo va leksikologiya boʻyicha oʻtilgan asosiy tushunchalarni tizimlashtirish.",explanation:"Unli va undoshlar, boʻgʻin, urgʻu, imlo qoidalari, leksikologik hodisalar (sinonim, antonim, omonim, paronim) va lugʻatlar bilan ishlash.",examples:["Fonetika, imlo va leksikologiya mashqlari"],verificationStatus:"verified",curriculumPosition:23},{id:"G6-L22",grade:6,lessonNumber:22,title:"Feʼl vazifa shakllari",topic:"Morfologiya — Feʼl",learningObjective:"Feʼlning vazifa shakllarini (harakat nomi, sifatdosh, ravishdosh) taniy olish va ularni gapda qoʻllay olish.",prerequisites:"Feʼl asosi, feʼl tushunchasi (5-sinf), gap boʻlaklari.",coreConcept:"Feʼlning vazifa shakllari — feʼldan yasalib, boshqa soʻz turkumlari vazifasida keladigan shakllar (harakat nomi, sifatdosh, ravishdosh).",explanation:"Harakat nomi ot vazifasida (-ish, -moq), sifatdosh sifat vazifasida (-gan, -adigan, -ar), ravishdosh ravish vazifasida (-ib, -a, -y, -gancha, -guncha) keladi.",rules:["Harakat nomi otlarning barcha belgilariga ega (egalik, kelishik, son).","Sifatdosh sifatlarning barcha belgilariga ega (otlashish, darajalanish).","Ravishdosh ravishlarning barcha belgilariga ega.","Vazifa shakllari feʼl maʼnosini saqlaydi."],examples:["Oʻqish — bilim olishning eng yaxshi usuli. (harakat nomi)","Kelgan mehmonlar — hammasi yigʻildi. (sifatdosh)","U kelib ketdi. (ravishdosh)"],commonMistakes:["Harakat nomini oddiy ot bilan adashtirish (oʻqish vs kitob)","Sifatdoshni oddiy sifat bilan adashtirish (kelgan vs yangi)","Ravishdoshni oddiy ravish bilan adashtirish (kelib vs tez)"],guidedPractice:["Oʻqish — eng yaxshi kasb. (harakat nomi)","Kelgan mehmon — uy egasi. (sifatdosh)","U kelib ketdi. (ravishdosh)"],independentPractice:["Har bir vazifa shakliga 3 tadan misol yozing.","Berilgan feʼllardan harakat nomi, sifatdosh va ravishdosh yasang: oʻqimoq, yozmoq, kelmoq, ketmoq"],answersExplanations:["Harakat nomi: oʻqish, yozish, kelish","Sifatdosh: oʻqigan, yozgan, kelgan","Ravishdosh: oʻqib, yozib, kelib"],lessonRecap:"Feʼlning vazifa shakllari — harakat nomi (ot vazifasida), sifatdosh (sifat vazifasida), ravishdosh (ravish vazifasida).",verificationStatus:"verified",curriculumPosition:24},{id:"G6-L23",grade:6,lessonNumber:23,title:"Sifat",topic:"Morfologiya — Sifat",learningObjective:"Sifatlarni taniy olish, ularning turlari, darajalari va yasalish usullarini bilish.",prerequisites:"Soʻz turkumlari (5-sinf), ot.",coreConcept:"Sifat — predmetning belgi-xususiyatini, rangini, hajmini, shaklini, sifatini bildiruvchi soʻz turkumi.",explanation:"Sifatlar maʼno guruhlariga (sifat, rang, hajm, shakl, vaqt) va darajalariga (oddiy, qiyosiy, orttirma, ozaytirma) boʻlinadi.",rules:["Oddiy daraja: chiroyli, katta, baland","Qiyosiy daraja: chiroyliroq, kattaroq (-roq)","Orttirma daraja: eng chiroyli, juda katta","Ozaytirma daraja: chiroyligina, kattagina (-gina)"],examples:["Yangi kitob","Qizil gul","Katta uy","Dumaloq stol","Ertagi kun"],commonMistakes:["Sifatni ot bilan adashtirish","Sifat darajalarini notoʻgʻri qoʻllash"],guidedPractice:["yangi, oq, katta, baland, goʻzal, qizil, issiq, yaxshi, qisqa, ertagi"],independentPractice:["Sifatlarning maʼno guruhlariga 3 tadan misol yozing.","Berilgan sifatlarni darajalang: chiroyli, katta, baland, yaxshi"],answersExplanations:["Oddiy: chiroyli; Qiyosiy: chiroyliroq; Orttirma: eng chiroyli; Ozaytirma: chiroyligina"],lessonRecap:"Sifat — predmetning belgi-xususiyatini bildiruvchi soʻz turkumi. Darajalari: oddiy, qiyosiy, orttirma, ozaytirma.",verificationStatus:"verified",curriculumPosition:25},{id:"G6-L24",grade:6,lessonNumber:24,title:"Son",topic:"Morfologiya — Son",learningObjective:"Sonlarni taniy olish, ularning maʼno guruhlari va turlarini bilish.",prerequisites:"Soʻz turkumlari (5-sinf), ot, sifat.",coreConcept:"Son — predmetning miqdori va tartibini bildiruvchi soʻz turkumi.",explanation:"Sonlar sanoq, dona, chama, jamlovchi, taqsim, kasr va tartib sonlarga boʻlinadi.",rules:["Sanoq sonlar: bir, ikki, uch","Dona sonlar: bitta, ikkita (-ta)","Chama sonlar: yigirmacha, yuzlab","Jamlovchi sonlar: uchov, toʻrtov (-ov)","Taqsim sonlar: ikkitadan (-tadan)","Kasr sonlar: yarim, chorak, uchdan bir","Tartib sonlar: birinchi, ikkinchi (-inchi)"],examples:["Bir kitob","Bitta olma","Birinchi sinf","Uchov keldi","Yarim non"],commonMistakes:["Sanoq va dona sonlarni adashtirish","Tartib sonlarni notoʻgʻri qoʻllash"],guidedPractice:["bir, ikkita, beshinchi, uchov, yarim, toʻrttadan, yuzlab"],independentPractice:["Har bir maʼno guruhiga 3 tadan misol yozing.","Sonlarni tartib sonlarga aylantiring."],answersExplanations:["Sanoq: bir; Dona: ikkita; Tartib: beshinchi; Jamlovchi: uchov; Kasr: yarim; Taqsim: toʻrttadan; Chama: yuzlab"],lessonRecap:"Son — predmetning miqdori va tartibini bildiruvchi soʻz turkumi.",verificationStatus:"verified",curriculumPosition:26},{id:"G6-L25",grade:6,lessonNumber:25,title:"Ravish",topic:"Morfologiya — Ravish",learningObjective:"Ravishlarni taniy olish, ularning yasalishi va maʼno turlarini bilish.",prerequisites:"Soʻz turkumlari (5-sinf), feʼl, sifat.",coreConcept:"Ravish — ish-harakatning belgisini, holatini, paytini, oʻrnini, miqdorini, darajasini bildiruvchi soʻz turkumi.",explanation:"Ravishlar holat (tez, sekin), payt (kecha, bugun), oʻrin (u yerda, bu yerda), miqdor-daraja (koʻp, juda) ravishlariga boʻlinadi.",rules:["Holat ravishi: tez, sekin, yaxshi","Payt ravishi: kecha, bugun, ertaga, hozir","Oʻrin ravishi: u yerda, bu yerda, tashqarida","Miqdor-daraja ravishi: koʻp, oz, juda, ancha"],examples:["Tez yugurdi","Kecha keldi","U yerda oʻqiydi","Juda yaxshi"],commonMistakes:["Ravishni sifat bilan adashtirish","Payt va oʻrin ravishlarini farqlamaslik"],guidedPractice:["U tez yugurdi.","Kecha keldi.","U yerda oʻqiydi.","Juda yaxshi."],independentPractice:["Har bir maʼno turiga 3 tadan misol yozing."],answersExplanations:["tez — holat, kecha — payt, u yerda — oʻrin, juda — miqdor-daraja"],lessonRecap:"Ravish — ish-harakatning belgisini bildiruvchi soʻz turkumi.",verificationStatus:"verified",curriculumPosition:27}],7:[{id:"G7-REV-03",grade:7,lessonNumber:null,isRevisionModule:!0,title:"REVISION MODULE 3: 7-SINF TAKRORLASH",topic:"Fonetika, imlo, qoʻshimchalar, leksikologiya, feʼl",learningObjective:"5-6 sinflarda oʻtilgan grammatik mavzularni takrorlash va mustahkamlash.",coreConcept:"Fonetika, imlo, soʻz yasalishi, leksikologiya hamda feʼl shakllari va zamonlarini takrorlash.",explanation:"Tovush oʻzgarishlari, qoʻshib va ajratib yozish, soʻz yasovchi va shakl yasovchi qoʻshimchalar, feʼl nisbatlari va zamonlari.",examples:["Grammatik takrorlash mashqlari"],verificationStatus:"verified",curriculumPosition:28},{id:"G7-L26",grade:7,lessonNumber:26,title:"Gumon va boʻlishsizlik olmoshlari",topic:"Morfologiya — Olmosh",learningObjective:"Gumon va boʻlishsizlik olmoshlarini taniy olish va toʻgʻri qoʻllash.",prerequisites:"Olmosh tushunchasi (7-sinf), soʻroq olmoshlari.",coreConcept:"Gumon olmoshlari — noaniq maʼno ifodalaydi. Boʻlishsizlik olmoshlari — mavjud emaslikni ifodalaydi.",explanation:'Gumon olmoshlari soʻroq olmoshlariga -dir qoʻshib yasaladi (kimdir, nimadir). Boʻlishsizlik olmoshlari "hech" soʻzi bilan yasaladi (hech kim, hech narsa).',rules:["Gumon olmoshlari: kimdir, nimadir, qandaydir, qayerdadir, allaqanday","Boʻlishsizlik olmoshlari: hech kim, hech narsa, hech qanday, hech qayerda","Boʻlishsizlik olmoshlari inkor feʼl bilan birga keladi.","Gumon va boʻlishsizlik olmoshlari ajratib yoziladi (hech kim)."],examples:["Kimdir eshikni taqillatdi.","Hech kim eshikni taqillatmadi.","Nimadir topdim.","Hech narsa topmadi."],commonMistakes:["hechkim deb qoʻshib yozish (toʻgʻrisi: hech kim)","Boʻlishsizlik olmoshini tasdiq gapda qoʻllash"],guidedPractice:["Kimdir eshikni ochdi.","Hech kim eshikni ochmadi.","Nimadir topdim."],independentPractice:["Gumon olmoshlari ishtirokida 3 ta gap tuzing.","Boʻlishsizlik olmoshlari ishtirokida 3 ta gap tuzing."],answersExplanations:["Kimdir — gumon olmoshi","Hech kim — boʻlishsizlik olmoshi"],lessonRecap:"Gumon olmoshlari noaniqlikni (-dir), boʻlishsizlik olmoshlari inkorlikni (hech) ifodalaydi va ajratib yoziladi.",verificationStatus:"verified",curriculumPosition:29},{id:"G7-L27",grade:7,lessonNumber:27,title:"Koʻmakchi, bogʻlovchi va yuklama",topic:"Yordamchi soʻzlar",learningObjective:"Koʻmakchi, bogʻlovchi va yuklamalarni taniy olish va ularni toʻgʻri qoʻllash.",prerequisites:"Yordamchi soʻzlar haqida tushuncha, soʻz birikmasi.",coreConcept:"Koʻmakchilar, bogʻlovchilar va yuklamalar — yordamchi soʻz turkumlari.",explanation:"Koʻmakchi soʻzlar orasidagi munosabatni (bilan, uchun, kabi), bogʻlovchi soʻz va gaplarni bogʻlaydi (va, agar, chunki), yuklama esa maʼnoni kuchaytiradi yoki oʻzgartiradi (-mi, -ku, faqat).",rules:["Koʻmakchilar: bilan, uchun, kabi, singari, sari, sayin","Teng bogʻlovchilar: va, hamda, bilan, yoki, yo...yo","Ergashtiruvchi bogʻlovchilar: agar, chunki, toki","Yuklamalar: -mi, -chi, -ku, -da, -u(-yu), faqat, ham"],examples:["U bilan keldi.","Siz uchun qildi.","U va men keldik.","Agar kelsa...","Keldimi?","Keldi-ku!"],commonMistakes:["Koʻmakchini bogʻlovchi bilan adashtirish","Yuklamalarni qoʻshib notoʻgʻri yozish"],guidedPractice:["U bilan keldi.","Agar kelsa...","Keldimi?","Chunki u keldi."],independentPractice:["Koʻmakchi, bogʻlovchi va yuklamalarga 3 tadan misol yozing."],answersExplanations:["bilan — koʻmakchi","agar — ergashtiruvchi bogʻlovchi","mi — soʻroq yuklamasi"],lessonRecap:"Yordamchi soʻzlar (koʻmakchi, bogʻlovchi, yuklama) gapdagi munosabat va maʼno jilolarini koʻrsatadi.",verificationStatus:"verified",curriculumPosition:30},{id:"G7-L28",grade:7,lessonNumber:28,title:"Undov, taqlid va modal soʻzlar",topic:"Alohida guruh soʻzlar",learningObjective:"Undov, taqlid va modal soʻzlarni taniy olish va ularni toʻgʻri qoʻllash.",prerequisites:"Yordamchi soʻzlar, soʻz turkumlari.",coreConcept:"Undov, taqlid va modal soʻzlar his-hayajon, tovush/holat taqlidi va soʻzlovchi munosabatini ifodalaydi.",explanation:"Undov soʻzlar his-hayajonni (voy, oh), taqlid soʻzlar tovush yoki holatni (sharaq, tar-tar), modal soʻzlar esa fikrga munosabatni (albatta, ehtimol) bildiradi.",rules:["Undov soʻzlar: voy, oh, eh, hey, qani","Taqlid soʻzlar: sharaq, tar-tar, chirs, yalt-yult","Modal soʻzlar: albatta, shubhasiz, ehtimol, balki, afsus"],examples:["Voy, qanday goʻzal!","Sharaq — eshik ochildi.","Albatta, u keladi.","Ehtimol, u kelmas."],commonMistakes:["Undov soʻzlardan keyin vergul qoʻymaslik","Taqlid va modal soʻzlarni imlosida xatolik"],guidedPractice:["Voy, qanday goʻzal!","Sharaq — eshik ochildi.","Albatta, u keladi."],independentPractice:["Undov, taqlid va modal soʻzlarga 3 tadan misol yozing."],answersExplanations:["Voy — undov","Sharaq — taqlid","Albatta — modal"],lessonRecap:"Undov (his-hayajon), taqlid (tovush/holat) va modal (munosabat) soʻzlar alohida guruh soʻz turkumlari hisoblanadi.",verificationStatus:"verified",curriculumPosition:31}],8:[{id:"G8-REV-04",grade:8,lessonNumber:null,isRevisionModule:!0,title:"REVISION MODULE 4: 8-SINF TAKRORLASH",topic:"Soʻz turkumlari va matn turlari",learningObjective:"Soʻz turkumlari va matn turlarini takrorlash.",coreConcept:"Mustaqil va yordamchi soʻz turkumlari hamda matn turlarini (hikoya, tasviriy, muhokama) takrorlash.",explanation:"6 ta mustaqil, 3 ta yordamchi va 3 ta alohida guruh soʻz turkumlari hamda hikoya, tasviriy, muhokama matnlarining tuzilishi.",examples:["Matn tahlili mashqlari"],verificationStatus:"verified",curriculumPosition:32},{id:"G8-L29",grade:8,lessonNumber:29,title:"Insho",topic:"Nutq oʻstirish — Yozma ish",learningObjective:"Insho yozish koʻnikmalarini shakllantirish, insho turlarini bilish va reja tuzish.",prerequisites:"Matn turlari (5-sinf), matn tahlili.",coreConcept:"Insho — oʻquvchining ijodiy yozma ishi boʻlib, unda muayyan mavzu boʻyicha fikr-mulohazalar, taassurotlar, xulosalar bayon qilinadi.",explanation:"Insho turlari: rivoya (hikoya), muhokama (mantiqiy fikr), tasviriy insho. Insho reja (sodda yoki murakkab) va epigraf bilan shakllantiriladi.",rules:["Insho mavzuga mos boʻlishi kerak.","Reja asosida mantiqiy izchil yozilishi kerak.","Til meʼyorlariga amal qilish va epigrafni toʻgʻri tanlash zarur."],examples:["Men bir kun... (rivoya)","Menimcha, kitob oʻqish... (muhokama)","Men sevgan gul... (tasviriy)"],commonMistakes:["Mavzudan chetga chiqish","Rejasiz yozish","Mantiqiy izchillikni buzish"],guidedPractice:["Sevimli kitobim mavzusiga reja tuzing."],independentPractice:["Oʻzingiz tanlagan mavzuda insho yozing.","Epigraf tanlang va sharhlang."],answersExplanations:["Reja: 1. Kirish 2. Asosiy qism 3. Xulosa"],lessonRecap:"Insho — reja va mantiqiy izchillik asosida yoziladigan ijodiy yozma ish.",verificationStatus:"verified",curriculumPosition:33},{id:"G8-L30",grade:8,lessonNumber:30,title:"Ajratilgan boʻlaklar",topic:"Sintaksis — Gap boʻlaklari",learningObjective:"Ajratilgan boʻlaklarni taniy olish va ularni toʻgʻri qoʻllash.",prerequisites:"Gap boʻlaklari (8-sinf), uyushiq boʻlaklar.",coreConcept:"Ajratilgan boʻlaklar — gapda alohida ohang bilan aytiladigan, izohlab keladigan boʻlaklar.",explanation:"Ajratilgan boʻlaklar gapdagi biror boʻlakni izohlaydi va aniqlashtiradi. Ajratilgan hol, toʻldiruvchi, aniqlovchi boʻladi va vergul, tire yoki qavs bilan ajratiladi.",rules:["Ajratilgan boʻlaklar alohida ohang bilan aytiladi.","Vergul, tire yoki qavs bilan ajratiladi."],examples:["U sekin, asta, shoshilmasdan gapirdi. (ajratilgan hol)","Kitobni, oʻquv qoʻllanmasini, oldim. (ajratilgan toʻldiruvchi)","Gul, qizil atirgul, derazada turardi. (ajratilgan aniqlovchi)"],commonMistakes:["Ajratilgan boʻlaklarni vergul bilan ajratmaslik","Ajratilgan boʻlaklarni uyushiq boʻlaklar bilan adashtirish"],guidedPractice:["U sekin, asta gapirdi.","Kitobni, oʻquv qoʻllanmasini, oldim."],independentPractice:["Ajratilgan hol, toʻldiruvchi va aniqlovchili 3 tadan gap tuzing."],answersExplanations:["sekin, asta — ajratilgan hol","Kitobni, oʻquv qoʻllanmasini — ajratilgan toʻldiruvchi"],lessonRecap:"Ajratilgan boʻlaklar gap boʻlaklarini izohlab, alohida ohang va tinish belgilari bilan ajratiladi.",verificationStatus:"verified",curriculumPosition:34},{id:"G8-L31",grade:8,lessonNumber:31,title:"Kiritma va undalma",topic:"Sintaksis — Gapning alohida ajratilgan qismlari",learningObjective:"Kiritma va undalmalarni taniy olish va ularni toʻgʻri qoʻllash.",prerequisites:"Gap boʻlaklari (8-sinf), ajratilgan boʻlaklar.",coreConcept:"Kiritma — fikrga munosabat bildiruvchi qism. Undalma — nutq qaratilgan shaxs yoki narsa.",explanation:"Kiritma va undalma gapning boshqa boʻlaklari bilan grammatik bogʻlanmagan. Ular alohida ohang va tinish belgilar (vergul, undov) bilan ajratiladi.",rules:["Kiritma gap boʻlaklari bilan bogʻlanmaydi: albatta, ehtimol, afsus, xayriyat","Undalma nutq qaratilgan shaxs/narsa boʻlib, bosh kelishikda boʻladi.","Vergul yoki undov belgisi bilan ajratiladi."],examples:["Albatta, u keladi.","Ehtimol, u kelmas.","Oʻqituvchi, bugun dars bormi?","Doʻstim, kel!"],commonMistakes:["Kiritmani gap boʻlagi deb hisoblash","Undalmani ega deb hisoblash","Tinish belgilarini tushirib qoldirish"],guidedPractice:["Albatta, u keladi.","Oʻqituvchi, bugun dars bormi?"],independentPractice:["Kiritma va undalma ishtirokida 5 tadan gap tuzing."],answersExplanations:["Albatta — kiritma (ishonch)","Oʻqituvchi — undalma"],lessonRecap:"Kiritma va undalmalar grammatik jihatdan gap boʻlaklari bilan bogʻlanmaydi va tinish belgilari bilan ajratiladi.",verificationStatus:"verified",curriculumPosition:35}],9:[{id:"G9-REV-05",grade:9,lessonNumber:null,isRevisionModule:!0,title:"REVISION MODULE 5: 9-SINF TAKRORLASH",topic:"Sintaksis va soʻz birikmasi",learningObjective:"8-sinfda oʻtilgan soʻz birikmasi, gap boʻlaklari hamda undalmali va kirish soʻzli gaplarni takrorlash va mustahkamlash.",coreConcept:"Soʻz birikmasi turlari, gap boʻlaklari va ajratilgan hamda kiritma boʻlaklarni tizimlashtirish.",explanation:"Hokim va tobe soʻz, bitishuv, boshqaruv, moslashuv hamda ega, kesim, toʻldiruvchi, aniqlovchi, hol va kiritmalarni takrorlash.",examples:["Soʻz birikmasi va gap tahlili mashqlari"],verificationStatus:"verified",curriculumPosition:36},{id:"G9-L32",grade:9,lessonNumber:32,title:"Sodda va qoʻshma gaplar",topic:"Sintaksis — Qoʻshma gap",learningObjective:"Sodda va qoʻshma gaplarni farqlay olish.",prerequisites:"Gap tushunchasi (8-sinf), kesim.",coreConcept:"Bitta kesimlik belgisiga ega boʻlgan gap sodda, ikki yoki undan ortiq sodda gapning oʻzaro grammatik va mazmuniy munosabatidan tashkil topgan butunlik qoʻshma gap sanaladi.",explanation:"Gap uchun muhim belgi kesimlikdir. Kesimning nechtaligi gaplarni sodda va qoʻshma gaplarga ajratishga asos boʻladi.",rules:["Sodda gapda bitta grammatik asos boʻladi.","Qoʻshma gapda ikki yoki undan ortiq grammatik asos boʻladi.","Qoʻshma gap qismlari bogʻlovchi vositalar yoki ohang orqali bogʻlanadi.","Sodda gapni qoʻshma gapdan kesimlar soniga qarab farqlash mumkin."],examples:["Men oʻquvchiman. (sodda gap)","Olim boʻlsang, olam seniki. (qoʻshma gap)","Eshik ochildi va u kirdi. (qoʻshma gap)"],commonMistakes:["Sodda gapni qoʻshma gap deb hisoblash","Qoʻshma gapni sodda gap deb hisoblash","Kesimlarni notoʻgʻri aniqlash"],guidedPractice:["Men maktabga bordim. (sodda)","Olim boʻlsang, olam seniki. (qoʻshma)","Eshik ochildi va u kirdi. (qoʻshma)"],independentPractice:["Sodda va qoʻshma gaplarga 5 tadan misol yozing.","Berilgan matndan sodda va qoʻshma gaplarni ajrating."],answersExplanations:["Sodda: bitta kesim (bordim)","Qoʻshma: ikki kesim (boʻlsang, seniki)"],lessonRecap:"Sodda gapda bitta, qoʻshma gapda ikki yoki undan ortiq kesim boʻladi.",verificationStatus:"verified",curriculumPosition:37},{id:"G9-L33",grade:9,lessonNumber:33,title:"Qoʻshma gap qismlari va bogʻlovchi vositalar",topic:"Sintaksis — Qoʻshma gap",learningObjective:"Qoʻshma gap qismlarini bogʻlovchi vositalarni taniy olish.",prerequisites:"Sodda va qoʻshma gaplar (Dars 32), bogʻlovchilar (7-sinf).",coreConcept:"Qoʻshma gap qismlarini bogʻlovchi vositalar: bogʻlovchilar, bogʻlovchi vazifasidagi vositalar va ohang.",explanation:"Qoʻshma gap qismlari teng bogʻlovchilar, ergashtiruvchi bogʻlovchilar, yuklamalar yoki ohang yordamida bogʻlanadi.",rules:["Teng bogʻlovchilar: va, ammo, lekin, biroq, yoki","Ergashtiruvchi bogʻlovchilar: agar, chunki, toki","Yuklama va bogʻlovchi soʻzlar: -u(-yu), -da, boʻlsa, esa, shuning uchun","Ohang: bogʻlovchisiz qoʻshma gaplarda"],examples:["Oʻzingga doʻst tanla, chunki bir oʻzing baxtli boʻlolmaysan.","Eshik ochildi va u kirdi.","Yomgʻir yogʻdi — koʻchalar namlandi."],commonMistakes:["Bogʻlovchi vositalarni notoʻgʻri aniqlash","Teng va ergashtiruvchi bogʻlovchini farqlamaslik"],guidedPractice:["Doʻstlikdan oʻtadigan hech narsa yoʻq, shuning uchun doʻst orttir.","Oʻzingga doʻst tanla, chunki bir oʻzing baxtli boʻlolmaysan."],independentPractice:["Turli bogʻlovchi vositalar yordamida 5 ta qoʻshma gap tuzing."],answersExplanations:["shuning uchun — koʻmakchili qurilma","chunki — ergashtiruvchi bogʻlovchi"],lessonRecap:"Qoʻshma gap qismlari bogʻlovchilar, bogʻlovchi vazifasidagi vositalar va ohang orqali bogʻlanadi.",verificationStatus:"verified",curriculumPosition:38},{id:"G9-L34",grade:9,lessonNumber:34,title:"Qoʻshma gaplar tasnifi",topic:"Sintaksis — Qoʻshma gap",learningObjective:"Qoʻshma gap turlarini farqlay olish.",prerequisites:"Qoʻshma gap qismlari va bogʻlovchi vositalar (Dars 33).",coreConcept:"Qoʻshma gaplar uch guruhga boʻlinadi: bogʻlangan, ergashgan va bogʻlovchisiz qoʻshma gaplar.",explanation:"Bogʻlangan qoʻshma gaplarda qismlar teng bogʻlovchilar bilan, ergashgan qoʻshma gaplarda ergashtiruvchi bogʻlovchilar bilan, bogʻlovchisiz qoʻshma gaplarda ohang yordamida bogʻlanadi.",rules:["Bogʻlangan qoʻshma gaplarda qismlar teng huquqli.","Ergashgan qoʻshma gaplarda bosh va ergash gap farqlanadi.","Bogʻlovchisiz qoʻshma gaplarda ohang va tinish belgilari muhim."],examples:["Eshik ochildi va u kirdi. (bogʻlangan)","Olim boʻlsang, olam seniki. (ergashgan)","Suv keldi — choʻllarda hayot boshlandi. (bogʻlovchisiz)"],commonMistakes:["Bogʻlangan va ergashgan qoʻshma gaplarni farqlamaslik","Bogʻlovchisiz qoʻshma gaplarni notoʻgʻri aniqlash"],guidedPractice:["Eshik ochildi va u kirdi. (bogʻlangan)","Olim boʻlsang, olam seniki. (ergashgan)"],independentPractice:["Har bir turga 3 tadan qoʻshma gap tuzing."],answersExplanations:["va — teng bogʻlovchi","boʻlsang — shart mayli"],lessonRecap:"Qoʻshma gaplar bogʻlangan, ergashgan va bogʻlovchisiz turlarga boʻlinadi.",verificationStatus:"verified",curriculumPosition:39},{id:"G9-L35",grade:9,lessonNumber:35,title:"Bogʻlangan qoʻshma gaplar — biriktiruv bogʻlovchilari",topic:"Sintaksis — Bogʻlangan qoʻshma gap",learningObjective:"Biriktiruv bogʻlovchilari yordamida bogʻlangan qoʻshma gaplarni taniy olish.",prerequisites:"Qoʻshma gaplar tasnifi (Dars 34).",coreConcept:"Biriktiruv bogʻlovchisi qoʻshma gapning payt, sabab-natija munosabatlarida boʻlgan qismlarini bogʻlaydi.",explanation:"Biriktiruv bogʻlovchilari: va, hamda, bilan, ham, -u(-yu), -da. Qismlar bir-biriga qoʻshilib bir butunlik hosil qiladi.",rules:["Biriktiruv bogʻlovchilari: va, hamda, -u(-yu), -da","Qismlar ketma-ketlik, sabab-natija munosabatida boʻladi.","-u(-yu), -da yuklamalari chiziqcha bilan yoziladi."],examples:["Toʻsatdan eshik sharaqlab ochildi va ostonada Ertoyev paydo boʻldi.","Keldi-u ketdi."],commonMistakes:["-u(-yu), -da ni bogʻlovchi sifatida tanimaslik","Yuklamalarni chiziqchasiz yozish"],guidedPractice:["Toʻsatdan eshik ochildi va u kirdi.","Keldi-u ketdi."],independentPractice:["Biriktiruv bogʻlovchilari ishtirokida 5 ta gap tuzing."],answersExplanations:["va — teng bogʻlovchi","-u — chiziqchali yuklama"],lessonRecap:"Biriktiruv bogʻlovchilari (va, hamda, -u, -da) qoʻshma gap qismlarini bogʻlaydi.",verificationStatus:"verified",curriculumPosition:40},{id:"G9-L36",grade:9,lessonNumber:36,title:"Bogʻlangan qoʻshma gaplar — zidlov va ayiruv bogʻlovchilari",topic:"Sintaksis — Bogʻlangan qoʻshma gap",learningObjective:"Zidlov va ayiruv bogʻlovchilari yordamida bogʻlangan qoʻshma gaplarni taniy olish.",prerequisites:"Bogʻlangan qoʻshma gaplar (Dars 35).",coreConcept:"Zidlov bogʻlovchilari zidlikni, ayiruv bogʻlovchilari esa galma-gal roʻy berish yoki bittasining yuzaga chiqishini ifodalaydi.",explanation:"Zidlov: ammo, lekin, biroq. Ayiruv: yoki, yo...yo, goh...goh, dam...dam.",rules:["Zidlov bogʻlovchilari: ammo, lekin, biroq","Ayiruv bogʻlovchilari: yoki, yo...yo, goh...goh, dam...dam","Takroriy ayiruv bogʻlovchilarida vergul qoʻyiladi."],examples:["Ashula nihoyasiga yetdi, lekin bir zumdan keyin yana yangi tovush parvoz qildi.","Yo siz keling, yo men boray."],commonMistakes:["Zidlov va ayiruv bogʻlovchilarini adashtirish","Takroriy bogʻlovchida vergul qoʻymaslik"],guidedPractice:["Ashula nihoyasiga yetdi, lekin bir zumdan keyin yangi tovush yangradi.","Yo siz keling, yo men boray."],independentPractice:["Zidlov va ayiruv bogʻlovchilari ishtirokida 5 ta gap tuzing."],answersExplanations:["lekin — zidlov","yo...yo — ayiruv (takroriy)"],lessonRecap:"Zidlov bogʻlovchilari (ammo, lekin, biroq) zidlikni, ayiruv bogʻlovchilari (yoki, yo...yo) galma-gallikni bildiradi.",verificationStatus:"verified",curriculumPosition:41},{id:"G9-L37",grade:9,lessonNumber:37,title:"Bogʻlovchisiz qoʻshma gaplar",topic:"Sintaksis — Bogʻlovchisiz qoʻshma gap",learningObjective:"Bogʻlovchisiz qoʻshma gaplarni taniy olish va tinish belgilarini toʻgʻri qoʻllash.",prerequisites:"Qoʻshma gaplar tasnifi (Dars 34).",coreConcept:"Maxsus bogʻlovchi vositalarsiz, faqat ohang yordamida bogʻlangan qoʻshma gaplar bogʻlovchisiz qoʻshma gaplar sanaladi.",explanation:"Qismlar orasida ketma-ketlik (vergul), oʻxshatish/zidlash (tire) yoki izohlash (ikki nuqta) munosabatlari ifodalanadi.",rules:["Vergul: bir paytda yoki ketma-ket sodir boʻlganda","Tire: oʻxshatish, zidlash, shart munosabatida","Ikki nuqta: izohlash va sabab munosabatida"],examples:["Yigitlar daraxtlarni yumshatdilar, qizlar maktab hovlisini supurdilar.","Hamal keldi — amal keldi.","Bizning qarorimiz shu: hasharda barchamiz faol qatnashamiz."],commonMistakes:["Tinish belgilarini notoʻgʻri qoʻllash","Ohang va mazmuniy munosabatni inobatga olmaslik"],guidedPractice:["Yigitlar ishladilar, qizlar supurdilar. (vergul)","Hamal keldi — amal keldi. (tire)"],independentPractice:["Bogʻlovchisiz qoʻshma gaplarga 5 ta misol yozing."],answersExplanations:["vergul — ketma-ketlik","tire — oʻxshatish","ikki nuqta — izohlash"],lessonRecap:"Bogʻlovchisiz qoʻshma gaplarda ohang va tinish belgilari (vergul, tire, ikki nuqta) asosiy oʻrin tutadi.",verificationStatus:"verified",curriculumPosition:42}],10:[{id:"G10-REV-06",grade:10,lessonNumber:null,isRevisionModule:!0,title:"REVISION MODULE 6: 10-SINF KIRISH",topic:"Nutq uslublari",learningObjective:"Nutq uslublarini (soʻzlashuv, publitsistik, badiiy, ilmiy, rasmiy) takrorlash va farqlash.",coreConcept:"Nutq uslublarining oʻziga xos xususiyatlari va qoʻllanish sohalarini tizimlashtirish.",explanation:"Soʻzlashuv, publitsistik, badiiy, ilmiy va rasmiy-idoraviy uslublarning leksik va grammatik belgilari.",examples:["Matnlarning uslubiy tahlili mashqlari"],verificationStatus:"verified",curriculumPosition:43},{id:"G10-L38",grade:10,lessonNumber:38,title:"Oʻrinli va nooʻrin soʻzlar",topic:"Nutq madaniyati va uslubiyat",learningObjective:"Soʻzlarni oʻrinli qoʻllay olish va nooʻrin qoʻllangan soʻzlarni tuzatish.",prerequisites:"Leksikologiya (5-sinf), soʻz maʼnosi.",coreConcept:"Oʻrinli soʻz — mazmunga, uslubga va vaziyatga mos qoʻllangan soʻz.",explanation:"Soʻzlarni oʻrinli qoʻllash nutqning aniqligi va taʼsirchanligini taʼminlaydi. Nooʻrin soʻzlar maʼnoni buzadi.",rules:["Soʻz maʼnosiga va uslubga mos kelishi kerak.","Nutq vaziyatiga mos kelishi lozim.","Sinonim va paronimlarni toʻgʻri tanlash zarur."],examples:["Bugun havo issiq. (oʻrinli) vs Bugun havo qaynoq. (nooʻrin)","Kitob qiziqarli. (oʻrinli) vs Kitob goʻzal. (nooʻrin)"],commonMistakes:["Soʻzni maʼnosiga mos qoʻllamaslik","Haddan tashqari kuchaytiruvchi soʻzlarni nooʻrin ishlatish"],guidedPractice:["Bugun havo qaynoq. (tuzatish: issiq)","Kitob goʻzal. (tuzatish: qiziqarli)"],independentPractice:["Nooʻrin qoʻllangan soʻzlar ishtirokida 5 ta gap yozing va ularni tuzating."],answersExplanations:["qaynoq → issiq","goʻzal → qiziqarli"],lessonRecap:"Soʻzlarni mazmunga va uslubga mos oʻrinli qoʻllash nutq madaniyatining asosiy talabidir.",verificationStatus:"verified",curriculumPosition:44},{id:"G10-L39",grade:10,lessonNumber:39,title:"Nutqdagi taqiqlar (tabu)",topic:"Nutq madaniyati va etika",learningObjective:"Nutqiy taqiqlarni (tabu) tushunish va ularni toʻgʻri qoʻllash.",prerequisites:"Nutq madaniyati, oʻrinli soʻzlar (Dars 38).",coreConcept:"Nutqiy taqiqlar (tabu) — madaniy nutq qoidalariga koʻra qoʻpol soʻzlarni ishlatmaslik va ularni yumshoqroq ifodalar bilan almashtirish.",explanation:"Tabu soʻzlar oʻrniga madaniyatli nutqda evfemizmlar qoʻllanadi.",rules:["Qoʻpol va nojoʻya soʻzlardan saqlanish kerak.","Yoshi ulugʻ va hurmatli shaxslarga odob bilan murojaat qilinadi.","Tabu soʻzlar oʻrniga evfemizmlar qoʻllanadi."],examples:["qari → keksa, yoshi ulugʻ","kasal → betob, xastalangan","oʻlmoq → vafot etmoq"],commonMistakes:["Qoʻpol va beadab soʻzlarni ishlatish","Tabu soʻzlarni yumshoq muqobiliga almashtirmaslik"],guidedPractice:["qari → keksa","kasal → betob","oʻlmoq → vafot etmoq"],independentPractice:["Tabu soʻzlar va ularning yumshoq muqobillariga 5 tadan misol keltiring."],answersExplanations:["qari → keksa/yoshi ulugʻ","oʻlmoq → vafot etmoq"],lessonRecap:"Tabu soʻzlar oʻrniga yumshoq, odobli ifodalar qoʻllash odobli nutqning belgisidir.",verificationStatus:"verified",curriculumPosition:45},{id:"G10-L40",grade:10,lessonNumber:40,title:"Evfemizm va disfemizmlar",topic:"Leksik uslubiyat",learningObjective:"Evfemizm va disfemizmlarni taniy olish va ularni toʻgʻri qoʻllash.",prerequisites:"Nutqdagi taqiqlar (Dars 39).",coreConcept:"Evfemizm — qoʻpol soʻzlarning yumshoq, odobli muqobili. Disfemizm — yumshoq ifodaning qoʻpol, keskin shakli.",explanation:"Evfemizmlar odobli nutqda, disfemizmlar esa keskin va taʼsirchan nutqda qoʻllanadi.",rules:["Evfemizm: yumshoq, odobli ifoda (vafot etmoq)","Disfemizm: qoʻpol, keskin ifoda (oʻlik)","Evfemizmlar rasmiy va xushsuxandlik nutqida yetakchilik qiladi."],examples:["Evfemizm: betob, keksa, vafot etmoq","Disfemizm: oʻlik, tentak, mast"],commonMistakes:["Evfemizmni disfemizm bilan adashtirish","Nooʻrin oʻrinda disfemizm qoʻllash"],guidedPractice:["oʻlmoq → vafot etmoq (evfemizm)","marhum → oʻlik (disfemizm)"],independentPractice:["Evfemizm va disfemizmlarga 5 tadan misol keltiring."],answersExplanations:["vafot etmoq — evfemizm","oʻlik — disfemizm"],lessonRecap:"Evfemizm yumshoqlik va odobni, disfemizm esa keskinlik va qoʻpollikni ifodalaydi.",verificationStatus:"verified",curriculumPosition:46},{id:"G10-L41",grade:10,lessonNumber:41,title:"Olmoshlar uslubiyati",topic:"Morfologik uslubiyat",learningObjective:"Olmoshlarning uslubiy vazifalarini tushunish va ularni toʻgʻri qoʻllash.",prerequisites:"Olmosh turlari (7-sinf).",coreConcept:"Olmoshlar nutqda hurmat, kamtarlik, taʼkid va umumlashma maʼnolarini ifodalaydi.",explanation:"Siz va Ular hurmatni, Biz kamtarlikni (men oʻrnida), Oʻsha va Anavi taʼkidni ifodalaydi.",rules:["Siz, Ular — hurmat maʼnosida (birlikda ham)","Biz — kamtarlik maʼnosida (men oʻrnida)","Oʻsha, Anavi — taʼkid va ishora"],examples:["Siz keldingizmi? (hurmat)","Biz fikrimizni aytdik. (kamtarlik)","Oʻsha kun unutilmas. (taʼkid)"],commonMistakes:["Hurmatli shaxslarga sen deb murojaat qilish","Men olmoshini meʼyoridan ortiq takrorlash"],guidedPractice:["Siz keldingizmi? (hurmat)","Biz fikrimizni aytdik. (kamtarlik)"],independentPractice:["Olmoshlarning uslubiy vazifalariga 5 tadan misol keltiring."],answersExplanations:["Siz — hurmat","Biz — kamtarlik"],lessonRecap:"Olmoshlar hurmat, kamtarlik va taʼkid kabi uslubiy maʼno nozikliklarini beradi.",verificationStatus:"verified",curriculumPosition:47},{id:"G10-L42",grade:10,lessonNumber:42,title:"Sinonim va antonim uslubiyati",topic:"Leksik uslubiyat",learningObjective:"Sinonim va antonimlarning uslubiy vazifalarini tushunish va ularni toʻgʻri qoʻllash.",prerequisites:"Sinonim va antonim (5-sinf).",coreConcept:"Sinonimlar boʻyoqdorlik va uslubiy qatlamni, antonimlar esa zidlanish orqali taʼsirchanlikni oshiradi.",explanation:"Sinonimlar soʻzlashuv, badiiy va rasmiy uslublarga boʻlinadi. Antonimlar ziddiyat yaratadi.",rules:["Sinonimlar uslubiy qatlamga ega: oʻlmoq (soʻzlashuv) - vafot etmoq (rasmiy)","Antonimlar zidlanish orqali taʼsirchanlikni taʼminlaydi."],examples:["oʻlmoq (oddiy), vafot etmoq (rasmiy), jon bermoq (badiiy)","Yaxshi-yomon, issiq-sovuq"],commonMistakes:["Sinonimlarni uslubga mos tanlamaslik","Antonimlarni nooʻrin qoʻllash"],guidedPractice:["oʻlmoq → vafot etmoq (rasmiy)","kasal → betob (yumshoq)"],independentPractice:["Sinonim va antonimlarning uslubiy vazifalariga 5 tadan misol yozing."],answersExplanations:["vafot etmoq — rasmiy sinonim","betob — yumshoq sinonim"],lessonRecap:"Sinonimlar uslubiy qatlamni, antonimlar esa taʼsirchan zidlikni shakllantiradi.",verificationStatus:"verified",curriculumPosition:48},{id:"G10-L43",grade:10,lessonNumber:43,title:"Omonim va paronim uslubiyati",topic:"Leksik uslubiyat",learningObjective:"Omonim va paronimlarning uslubiy vazifalarini tushunish.",prerequisites:"Omonim va paronim (5-sinf).",coreConcept:"Omonimlar soʻz oʻyinlari va tajnis yaratish uchun, paronimlar esa dori kabi aniqlik va taʼsirchanlik uchun qoʻllanadi.",explanation:"Omonimlar shakldosh soʻzlar boʻlib, tajnis sanʼatida qoʻllanadi. Paronimlar soʻz qoʻllash aniqligini talab qiladi.",rules:["Omonimlar soʻz oʻyini va tajnis hosil qiladi.","Paronimlar maʼnosi nozik farqlanadi va aniqlik talab qiladi."],examples:["Burun (yuz) va Burun (avval) — omonim","Maʼnaviy va Moddiy — paronim"],commonMistakes:["Paronimlarni bir-biri bilan chalkashtirish","Omonimlar maʼnosini kontekstdan ajrata olmaslik"],guidedPractice:["Burun (yuz) vs Burun (avval)","Maʼnaviy va Moddiy"],independentPractice:["Omonim va paronimlar ishtirokida 5 tadan gap tuzing."],answersExplanations:["burun — omonim","maʼnaviy/moddiy — paronim"],lessonRecap:"Omonimlar tajnisda, paronimlar esa maʼno aniqligida muhim oʻrin tutadi.",verificationStatus:"verified",curriculumPosition:49},{id:"G10-L44",grade:10,lessonNumber:44,title:"Koʻhna va oʻzlashma soʻzlar uslubiyati",topic:"Leksik uslubiyat",learningObjective:"Koʻhna va oʻzlashma soʻzlarning uslubiy vazifalarini tushunish.",prerequisites:"Tarixiy soʻzlar va oʻzlashma soʻzlar (5-sinf).",coreConcept:"Koʻhna soʻzlar tarixiy davr va milliy koloritni, oʻzlashma soʻzlar zamonaviy fan va texnika sohasini ifodalaydi.",explanation:"Tarixiy va arxaik soʻzlar badiiy va tarixiy matnlarda kolorit beradi. Oʻzlashma soʻzlar ilm-fanda qoʻllanadi.",rules:["Koʻhna soʻzlar: amir, sulton, botir, shoh","Oʻzlashma soʻzlar: kompyuter, mobil, internet"],examples:["Ulugʻ ajdodlar, Amir Temur (koʻhna soʻzlar)","Kompyuter, mobil aloqa (oʻzlashma soʻzlar)"],commonMistakes:["Koʻhna soʻzlarni zamonaviy matnda nooʻrin qoʻllash","Oʻzlashma soʻzlarni xato yozish"],guidedPractice:["amir, sulton → koʻhna","kompyuter, internet → oʻzlashma"],independentPractice:["Koʻhna va oʻzlashma soʻzlarga 5 tadan misol keltiring."],answersExplanations:["amir — koʻhna soʻz","kompyuter — oʻzlashma soʻz"],lessonRecap:"Koʻhna soʻzlar tarixiy koloritni, oʻzlashma soʻzlar esa zamonaviylik va ilmiylikni ifodalaydi.",verificationStatus:"verified",curriculumPosition:50}],11:[{id:"G11-REV-07",grade:11,lessonNumber:null,isRevisionModule:!0,title:"REVISION MODULE 7: 11-SINF KIRISH",topic:"Talaffuz va imlo meʼyorlari",learningObjective:"Oʻzlashma soʻzlar talaffuzi, oʻzgaruvchi unli va undoshlar hamda urgʻu meʼyorlarini takrorlash.",coreConcept:"Adabiy tilning talaffuz va imlo meʼyorlarini umumlashtirish.",explanation:"Oʻzlashma soʻzlar talaffuzi, unli va undoshlar imlosi hamda urgʻuli boʻgʻinlar.",examples:["Talaffuz va imlo mashqlari"],verificationStatus:"verified",curriculumPosition:51},{id:"G11-L45",grade:11,lessonNumber:45,title:"Urgʻu talaffuzi",topic:"Orfoepiya va orfografiya",learningObjective:"Oʻzlashma soʻzlarda urgʻuni toʻgʻri qoʻllash va talaffuz qilish.",prerequisites:"Urgʻu (5-sinf).",coreConcept:"Oʻzlashma soʻzlarda urgʻu oʻzbekcha soʻzlardan farqli oʻlaroq turli boʻgʻinlarga tushishi mumkin.",explanation:"Oʻzbek tilida urgʻu asosan oxirgi boʻgʻinga tushadi, lekin oʻzlashma soʻzlarda urgʻu oʻz manbasini saqlab qolishi mumkin.",rules:["Oʻzbekcha soʻzlarda urgʻu oxirgi boʻgʻinga tushadi.","Oʻzlashma soʻzlarda urgʻu birinchi yoki oʻrta boʻgʻinga tushishi mumkin.","Urgʻuni toʻgʻri qoʻyish lugʻat orqali aniqlanadi."],examples:["kompyúter (urgʻu oʻrtada)","mobíl (urgʻu oxirida)","télevizor (urgʻu boshda)","internét (urgʻu oxirida)"],commonMistakes:["Oʻzlashma soʻzlarning urgʻusini oʻzbekcha qoidalarga koʻra majburiy oxiriga koʻchirish"],guidedPractice:["kompyúter","mobíl","télevizor","internét"],independentPractice:["Oʻzlashma soʻzlarga 10 ta misol topib, urgʻusini belgilang."],answersExplanations:["kompyúter — oʻrta boʻgʻinda","télevizor — birinchi boʻgʻinda"],lessonRecap:"Oʻzlashma soʻzlarda urgʻu oʻzbekcha soʻzlardan farq qilishi mumkin va orfoepik lugʻat bilan tekshiriladi.",verificationStatus:"verified",curriculumPosition:52},{id:"G11-L46",grade:11,lessonNumber:46,title:"Qoʻshib va ajratib yozish — umumlashtirish",topic:"Orfografiya",learningObjective:"Qoʻshib va ajratib yozish qoidalarini umumlashtirish va murakkab holatlarda toʻgʻri qoʻllash.",prerequisites:"Qoʻshib va ajratib yozish (5-sinf).",coreConcept:"Qoʻshma soʻzlar va baʼzi qoʻshimchalar qoʻshib, yordamchi soʻzlar va olmoshli birikmalar ajratib yoziladi.",explanation:"Qoʻshib yozish va ajratib yozish meʼyorlarini tizimli ravishda amalda qoʻllash.",rules:["Qoʻshma soʻzlar qoʻshib yoziladi (qoʻziqorin, belkurak).","Har bir, hech kim, shu bilan, oʻsha vaqt ajratib yoziladi.","Yordamchi soʻzlar ajratib yoziladi."],examples:["qoʻziqorin, belkurak (qoʻshib)","har bir, hech kim, shu bilan (ajratib)"],commonMistakes:["harbir, hechkim deb qoʻshib xato yozish","qoʻzi qorin deb ajratib xato yozish"],guidedPractice:["qoʻziqorin (qoʻshib)","har bir (ajratib)","hech kim (ajratib)"],independentPractice:["Qoʻshib va ajratib yozish qoidalariga 10 tadan misol keltiring."],answersExplanations:["qoʻziqorin — qoʻshib","har bir — ajratib"],lessonRecap:"Qoʻshma soʻzlar qoʻshib, ibora va yordamchili birikmalar ajratib yoziladi.",verificationStatus:"verified",curriculumPosition:53},{id:"G11-L47",grade:11,lessonNumber:47,title:"Ortiqcha qoʻshimchalar",topic:"Morfologik va nutqiy meʼyorlar",learningObjective:"Ortiqcha qoʻshimchalarni aniqlash va ularni nutqdan chiqarib tashlash.",prerequisites:"Morfologiya (6-sinf).",coreConcept:"Ortiqcha qoʻshimchalar — soʻzga keraksiz, maʼnoni takrorlaydigan va ortiqcha yuklama beradigan shakllardir.",explanation:"Soʻzga ortiqcha qoʻshimcha qoʻshish nutqiy gʻalizlik va mantiqsizlikka olib keladi.",rules:["Maʼno jihatdan keraksiz qoʻshimchalar ishlatilmaydi.","Bir-birini takrorlaydigan qoʻshimchalar ketma-ket qoʻllanmaydi."],examples:["kelgandaman → kelganman","ketgandasan → ketgansan","oʻqigandim → oʻqiganman"],commonMistakes:["-gan va -di qoʻshimchalarini ketma-ket nooʻrin qoʻllash"],guidedPractice:["kelgandaman → kelganman","ketgandasan → ketgansan"],independentPractice:["Ortiqcha qoʻshimchalarga 5 ta misol keltiring va tuzating."],answersExplanations:["kelgandaman → kelganman"],lessonRecap:"Ortiqcha qoʻshimchalarni chiqarib tashlash nutqning ixcham va aniq boʻlishini taʼminlaydi.",verificationStatus:"verified",curriculumPosition:54},{id:"G11-L48",grade:11,lessonNumber:48,title:"Qoʻshimchalar tanlovi",topic:"Morfologik va phonetik meʼyorlar",learningObjective:"Qoʻshimchalarni variantlardan toʻgʻri tanlay olish.",prerequisites:"Morfologiya (6-sinf).",coreConcept:"Qoʻshimcha variantlari (-ga/-ka/-qa, -da/-ta, -dan/-tan) asosning oxirgi tovushiga va fonetik qoidalarga koʻra tanlanadi.",explanation:"Asos jarangsiz undosh bilan tugasa, qoʻshimcha ham jarangsiz variantda tanlanadi.",rules:["Joʻnalish kelishigi: kitobga, kichikka, ishqa","Oʻrin-payt kelishigi: kitobda, kichikta","Chiqish kelishigi: kitobdan, kichiktan"],examples:["kitobga (ga), kichikka (ka), ishqa (qa)","kitobda (da), kichikta (ta)"],commonMistakes:["Kichikga deb xato yozish (toʻgʻrisi: kichikka)","Ishga deb xato yozish (toʻgʻrisi: ishqa)"],guidedPractice:["kitob + ga → kitobga","kichik + ga → kichikka","ish + ga → ishqa"],independentPractice:["Qoʻshimcha tanloviga 10 ta misol keltiring."],answersExplanations:["kitobga","kichikka","ishqa"],lessonRecap:"Qoʻshimcha variantlari asosning oxirgi tovushining jarangli/jarangsizligiga qarab tanlanadi.",verificationStatus:"verified",curriculumPosition:55},{id:"G11-L49",grade:11,lessonNumber:49,title:"Shakl va mazmun mosligi",topic:"Nutq madaniyati va stilistika",learningObjective:"Fikrni ixcham va aniq ifodalay olish, shakl va mazmun mosligiga erishish.",prerequisites:"Gap tuzilishi va nutq madaniyati.",coreConcept:"Shakl va mazmun mosligi — fikrning shakli (gap qurilishi) uning mazmuniga toʻliq mos va ixcham boʻlishi.",explanation:"Keraksiz va dabdabali soʻzlardan qutulib, fikrni sodda, loʻnda va taʼsirchan ifodalash.",rules:["Fikrni ixcham ifodalash — keraksiz tafsilotlardan saqlanish.","Fikrni aniq va mantiqiy izchil ifodalash."],examples:["Men bugun maktabga bordim. (ixcham)","Men bugun ertalab soat 8da maktabga bordim. (ortiqcha tafsilot)"],commonMistakes:["Fikrni haddan tashqari murakkablashtirish va shaffoflikni yoʻqotish"],guidedPractice:["Men bugun ertalab soat 8da maktabga bordim. → Men bugun maktabga bordim."],independentPractice:["Shakl va mazmun mosligiga 5 ta misol keltiring."],answersExplanations:["Sodda va ixcham variant toʻgʻri deb baholanadi."],lessonRecap:"Shakl va mazmun mosligi nutqning madaniyatli, mantiqiy va tushunarli boʻlishini kafolatlaydi.",verificationStatus:"verified",curriculumPosition:56},{id:"G11-L50",grade:11,lessonNumber:50,title:"Bayonnoma",topic:"Rasmiy-idoraviy uslub — Ish qogʻozlari",learningObjective:"Bayonnoma yozish koʻnikmalarini shakllantirish.",prerequisites:"Rasmiy uslub.",coreConcept:"Bayonnoma — majlis, yigʻilish va tadbirlarning borishi hamda qabul qilingan qarorlarini aks ettiruvchi rasmiy hujjat.",explanation:"Bayonnomada sana, joy, ishtirokchilar, kun tartibi, eshitildi va qaror qilindi qismlari tartib bilan yoziladi va imzolanadi.",rules:["Sana, joy va vaqt koʻrsatiladi.","Ishtirokchilar va kun tartibi beriladi.","Eshitildi va Qaror qilindi boʻlimlari shakllantiriladi.","Masʼul shaxs tomonidan imzolanadi."],examples:["Bayonnoma namunasi: Kun tartibi, Eshitildi, Qaror qilindi, Imzo."],commonMistakes:["Rasmiy uslub meʼyorlarini buzish","Qaror qilindi qismini imzolamaslik"],guidedPractice:["Maktab tadbiri uchun kun tartibi va qaror qismini tuzish"],independentPractice:["Maktabda oʻtkazilgan yigʻilish uchun bayonnoma namunasini yozing."],answersExplanations:["Bayonnoma tarkibiy qismlari toʻliq boʻlishi kerak."],lessonRecap:"Bayonnoma yigʻilish va majlis qarorlarini rasmiylashtiruvchi muhim ish qogʻozidir.",verificationStatus:"verified",curriculumPosition:57},{id:"G11-L51",grade:11,lessonNumber:51,title:"Bayonnomadan koʻchirma",topic:"Rasmiy-idoraviy uslub — Ish qogʻozlari",learningObjective:"Bayonnomadan koʻchirma yozish koʻnikmalarini shakllantirish.",prerequisites:"Bayonnoma (Dars 50).",coreConcept:"Bayonnomadan koʻchirma — asosiy bayonnomadagi muayyan bir qaror yoki bandning alohida rasmiy hujjati.",explanation:"Koʻchirmada qaysi bayonnoma va banddan olingani aniq koʻrsatiladi hamda rahbar yoki kotib tomonidan tasdiqlanadi.",rules:["Asosiy bayonnomaning sanasi va raqami koʻrsatiladi.","Qaysi banddan koʻchirma olingani belgilangan holda yoziladi.","Tasdiqlovchi imzo qoʻyiladi."],examples:["BAYONNOMADAN KOʻCHIRMA: 2024-yil 15-sentyabrdagi 2-sonli bayonnomadan koʻchirma."],commonMistakes:["Asosiy bayonnoma raqami va sanasini koʻrsatmaslik"],guidedPractice:["Bayonnomaning 2-bandidan koʻchirma rasmiylashtirish"],independentPractice:["Oʻzingiz tuzgan bayonnomadan bir band koʻchirma yozing."],answersExplanations:["Asosiy bayonnoma rekvizitlari va tasdiqlovchi imzo boʻlishi shart."],lessonRecap:"Bayonnomadan koʻchirma muayyan bir qarorni tegishli joyga taqdim etish uchun xizmat qiladi.",verificationStatus:"verified",curriculumPosition:58}]}};export{a as c};
